def review(n,title,q,proof,steps,scenes,checks,rule,hint,caption,refs):
    page=328 if n<=7 else 329
    c=lesson(n,None,page,q,proof,steps,scenes,checks,rule,hint,caption,
             'Сформулируй свой ответ и обоснуй его. Сверь выводы по построенным примерам.',refs=refs)
    c['id']=f'atanasyan-7-9-selfcheck-chapter-14-{n}-part-1'
    c['title']=f'Вопрос {n}. '+title
    c['source'].update(collection='selfcheck',chapter='XIV',exercise=str(n))
    c['review']['reviewer']=f'Атанасян и др., Геометрия 7–9, 14-е переработанное издание, 2023. Исходный вопрос {n} к главе XIV, печатная с. {page}, с. {page+1} выданного PDF. Проверены тема и собственные построения.'
    return c


def position(title,mode,points,v=(0,0)):
    def image(p):
        x,y=p
        if mode=='mirror':return (2*v[0]-x,y)
        if mode=='half':return (2*v[0]-x,2*v[1]-y)
        if mode=='turn':return (v[0]-(y-v[1]),v[1]+(x-v[0]))
        if mode=='stretch':return (2*x,y)
        if mode=='slide':return (x+v[0],y+v[1])
        raise ValueError(mode)
    pts={**points,**{k+'′':image(p) for k,p in points.items()}}
    edges=[]
    for suffix in ('','′'):
        if 'B' in points:edges.append(('A'+suffix,'B'+suffix))
        if 'C' in points:edges.extend([('B'+suffix,'C'+suffix),('C'+suffix,'A'+suffix)])
    if mode=='mirror':
        ys=[p[1] for p in pts.values()]
        pts['T']=(v[0],min(ys)-.6)
        marks=[((v[0],min(ys)-1),(v[0],max(ys)+1))]
    else:
        marks=[]
        if mode in ('half','turn'):pts['T']=v
    if len(points)==1 or mode in ('mirror','half'):
        edges.extend((k,k+'′') for k in points if pts[k]!=pts[k+'′'])
    return diagram(title,pts,edges,marks)


def mapping():
    return review(1,'Правило и обратное правило','Какие требования задают взаимно однозначное отображение плоскости на себя? Как проверить и образ, и прообраз?',
      'Каждой точке исходной плоскости по правилу ставится в соответствие ровно одна точка той же плоскости. И обратно, для каждой возможной конечной точки существует ровно одна исходная. Такую взаимно однозначную связь и называют преобразованием плоскости. Например, правило (x,y)↦(2x,y) обратимо: по (u,v) однозначно восстанавливается (u/2,v). Оно является преобразованием, хотя не сохраняет все расстояния.',
      [('Найди образ','Сначала попробуй простой сдвиг вправо. Одно правило должно дать каждой точке однозначный результат.','Однозначность результата ещё не гарантирует, что все точки плоскости появляются в качестве образов.'),
       ('Восстанови исходную точку','Во второй схеме абсциссу удваивают. У A′ абсцисса 6. Найди абсциссу A действием, обратным удвоению.','Обратное правило делит абсциссу пополам. Ещё одно удвоение не вернёт начало.'),
       ('Примени к отрицательному числу','В третьем чертеже исходная A имеет абсциссу −2. Проверь прямое правило и рассуди, может ли другая точка дать тот же образ целиком.','При удвоении отрицательной абсциссы знак сохраняется.')],
      [position('У каждого старта есть образ','slide',{'A':(1,1)},(2,0)),position('Найди прообраз абсциссы 6','stretch',{'A':(3,1)}),position('Отрицательная абсцисса','stretch',{'A':(-2,2)})],
      [('Чему равна x(A), если x(A′)=6 в правиле удвоения?','3','Раздели 6 на 2.'),('Чему равна x(A′), если x(A)=−2?','-4','Умножь абсциссу на 2.')],
      'Полное обратное правило сразу подтверждает и существование, и единственность прообраза.',
      'Проверь, можешь ли ты однозначно пройти назад от любой заданной точки.','A′ обозначает образ A.',[122])


def mirror_map():
    return review(2,'Обратимость зеркального отражения','Почему отражение относительно прямой является преобразованием всей плоскости?',
      'Для точки за осью опусти перпендикуляр на ось и отложи на другой стороне то же расстояние. Так возникает единственный образ. Точка на оси остаётся на месте. Повторное отражение в той же оси возвращает исходную точку, поэтому для каждой точки плоскости существует единственный прообраз — её отражение. Это доказывает взаимную однозначность.',
      [('Построй образ за осью','На первом чертеже проведена вертикальная ось. Исходная точка и её образ имеют одну ординату и одинаковые расстояния до оси.','Сохраняй расстояние по перпендикуляру к оси, а не по произвольной наклонной.'),
       ('Измени положение оси','Во втором примере ось x=1, точка A лежит при x=4. Найди x(A′) с другой стороны.','Менять знак x без учёта положения оси можно лишь для оси x=0.'),
       ('Вернись и проверь ось','В третьей схеме A лежит на оси x=2. Определи её смещение. У любой другой точки прообразом является её зеркальная точка.','То, что одна точка осталась на месте, не нарушает взаимной однозначности.')],
      [position('Отражение в оси x=0','mirror',{'A':(2,1)}),position('Ось сдвинута к x=1','mirror',{'A':(4,2)},(1,0)),position('Точка на оси x=2','mirror',{'A':(2,1)},(2,0))],
      [('Чему равна x(A′) во втором примере?','-2','От x=1 отступи на 3 налево.'),('Чему равно расстояние AA′, если A лежит на оси?','0','На оси A=A′.')],
      'Одно и то же отражение является обратным для самого себя.',
      'Построй образ дважды и отдельно рассмотри точку на оси.','Выделена ось отражения. T — её отмеченная точка.',[122])


def central_map():
    return review(3,'Обратимость полуоборота','Почему симметрия относительно точки T является преобразованием плоскости?',
      'Для A, отличной от T, продолжи луч AT за T и отложи TA′=TA, так что T окажется серединой AA′. Центр T переходит в себя. У любой точки A′ имеется прообраз, найденный применением того же правила ещё раз. Он единственен, потому что второй конец отрезка по одному концу и известной середине восстанавливается однозначно. Следовательно, это преобразование плоскости.',
      [('Найди второй конец','В первом рисунке центр находится между A и A′. Для центра самого образ совпадает с ним.','Если A′ остаётся на том же луче от T, условие середины может не выполниться.'),
       ('Восстанови абсциссу','Во второй схеме T=(2;1), A=(5;3). Найди абсциссу A′ из того, что 2 — среднее двух абсцисс.','Для центра не в начале координат нельзя просто поменять знак у обеих координат.'),
       ('Выполни обратный полуоборот','На третьем рисунке T=(1;2), а A′ имеет ординату 5. Вернись к A и найди её ординату.','Середина отрезка не меняется при чтении его концов в обратном направлении.')],
      [position('T посередине','half',{'A':(2,1)}),position('Центр T=(2;1)','half',{'A':(5,3)},(2,1)),position('Возвращение к исходной точке','half',{'A':(3,-1)},(1,2))],
      [('Какова абсцисса A′, если x(T)=2 и x(A)=5?','-1','x(A′)=2·2−5.'),('Какова ордината A, если y(T)=2 и y(A′)=5?','-1','y(A)=2·2−5.')],
      'Один и тот же центр задаёт и прямое, и обратное преобразование.',
      'Запиши координаты T как полусуммы координат A и A′.','A и A′ расположены по разные стороны от T.',[122])


def isometry():
    return review(4,'Проверка движения','Какое преобразование плоскости называют движением? Чем проверка одной пары отличается от проверки всех пар?',
      'Движение — такое преобразование плоскости, которое сохраняет расстояние между любыми двумя точками. Для любых A,B должно выполняться A′B′=AB. Если есть хотя бы одна пара с изменившейся длиной, преобразование движением не является. Равенство длин у одной специально подобранной пары не доказывает свойство для всех.',
      [('Сравни отрезок и его образ','Сдвиг всех точек на один вектор не меняет разности их координат. Значит, длина сохраняется для любой пары.','Смещение концов отрезка само по себе не означает изменения длины между ними.'),
       ('Проверь поворот','На втором чертеже AB имеет катеты по координатам 3 и 4. После четверти оборота вокруг T меняются направления, но не длина.','Расстояние точки от центра поворота и расстояние между двумя точками — разные величины.'),
       ('Найди контрпример','На третьем чертеже абсциссы удвоили, а ординаты сохранили. У горизонтального отрезка длины 3 изменилась длина, хотя вертикальные отрезки сохраняют свои длины.','Одного примера, где длина сохранилась, не хватит для утверждения обо всех парах.')],
      [position('Перенос всех точек','slide',{'A':(0,0),'B':(2,1)},(1,3)),position('Поворот прямоугольных приращений','turn',{'A':(1,0),'B':(4,4)}),position('Проверь растяжение','stretch',{'A':(1,1),'B':(4,1)})],
      [('Чему равна длина A′B′ во второй схеме?','5','Длина исходного отрезка √(9+16).'),('Чему равна длина образа горизонтального отрезка длины 3 при удвоении абсциссы?','6','Удваивается горизонтальное расстояние.')],
      'Отображение должно быть взаимно однозначным и сохранять все попарные расстояния.',
      'Чтобы опровергнуть движение, выбери пару точек, расстояние между которыми изменилось.','AB — исходный отрезок, A′B′ — его образ.',[122,123])


def mirror_length():
    return review(5,'Отражение и расстояние','Докажи, что зеркальное отражение относительно прямой является движением.',
      'Выбери координаты так, чтобы осью отражения была вертикальная прямая x=d. При отражении (x,y)↦(2d−x,y). Для двух точек разность их абсцисс меняет знак, разность ординат сохраняется. Квадраты обеих разностей и их сумма остаются прежними, значит, расстояние сохраняется для всякой пары. Отражение обратимо самим собой. Получили движение.',
      [('Сравни разности координат','Две исходные точки могут быть на одной или разных сторонах зеркала. Для разности абсцисс в обоих случаях получается противоположное значение.','Отражение меняет знак разности абсцисс, а не обязательно каждой её отдельной координаты.'),
       ('Проверь наклонный отрезок','Во втором примере у AB разности координат 3 и 4. После отражения относительно x=1 горизонтальная разность равна −3. Проверь длину.','Отрицательный знак одной компоненты не делает длину отрицательной.'),
       ('Проверь пересечение оси','В третьем примере A и B по разные стороны зеркала. Разности по модулю 5 и 12. Вычисли A′B′.','Не складывай расстояния от каждой точки до зеркала для получения полной наклонной длины.')],
      [position('Сверь обе компоненты','mirror',{'A':(1,1),'B':(3,2)}),position('Ось x=1 и катеты 3, 4','mirror',{'A':(-1,0),'B':(2,4)},(1,0)),position('Точки по разные стороны','mirror',{'A':(-3,-6),'B':(2,6)})],
      [('Какова длина A′B′ в примере с катетами 3 и 4?','5','Квадрат длины равен 25.'),('Какова длина A′B′ при модулях разностей 5 и 12?','13','Квадрат длины равен 25+144.')],
      'Равенство суммы квадратов разностей координат означает равенство евклидовых расстояний.',
      'Используй удобные координаты, сохранив общее положение двух точек.','Выделена ось. Прямой и отражённый отрезки имеют равные длины.',[122,123])


def central_length():
    return review(6,'Полуоборот и расстояние','Можно ли считать центральную симметрию движением? Докажи ответ для произвольных двух точек.',
      'Да. С началом координат в центре T полуоборот меняет (x,y) на (−x,−y). Для двух произвольных точек обе разности координат меняют знак. Следовательно, сумма их квадратов, а значит, и расстояние между точками сохраняется. Преобразование обратимо тем же полуоборотом. Доказательство включает пары на одной прямой с T и точки, совпадающие с центром.',
      [('Проверь середины','T одновременно является серединой AA′ и BB′. Сравни направление от A к B с направлением от A′ к B′.','Вектор между образами противоположен исходному; равны их длины.'),
       ('Возьми точки на одной прямой','Во второй модели A и B имеют абсциссы −2 и 5, ординаты нулевые. После полуоборота вычисли расстояние между их образами.','Если T между точками, длина AB не равна разности модулей координат.'),
       ('Перейди к наклонному отрезку','В третьей модели между A и B по горизонтали 6 единиц, по вертикали 8. Обоснуй равенство длин и назови численное значение.','При смене знака обеих компонент их квадраты сохраняются по отдельности.')],
      [position('Полуоборот общей пары','half',{'A':(1,2),'B':(4,1)}),position('Одна прямая с центром','half',{'A':(-2,0),'B':(5,0)}),position('Катеты 6 и 8','half',{'A':(-2,-3),'B':(4,5)})],
      [('Какова длина A′B′ для абсцисс A=−2, B=5?','7','Между образами 2 и −5 расстояние 7.'),('Какова длина A′B′ при компонентах 6 и 8?','10','√(36+64)=10.')],
      'Переход к противоположному вектору сохраняет его длину.',
      'Поставь начало координат в центр симметрии и выпиши формулы объектов до и после.','T — центр для обеих пар соответствующих точек.',[122,123])


def whole_segment():
    def section(title,L,x,dy):
        coords={'A':(0,0),'B':(L,0),'P':(x,0),'A′':(1,dy),'B′':(1+L,dy),'P′':(1+x,dy)}
        return schematic(title,coords,[('A','B'),('A′','B′'),('P','P′')])
    return review(7,'Отрезок переходит во весь отрезок','Докажи, что всякий отрезок AB при движении переходит в отрезок A′B′ с образами концов.',
      'Точка P лежит на AB тогда и только тогда, когда AP+PB=AB. Движение сохраняет все три расстояния. Поэтому для образа P′ выполнено A′P′+P′B′=A′B′, то есть P′ лежит на A′B′. Обратно: у любой точки отрезка A′B′ есть прообраз, и те же равенства в обратном порядке помещают его на AB. Значит, получен весь отрезок с обоими концами.',
      [('Установи принадлежность','На первой схеме P находится между A и B. Равенство длин характеризует принадлежность всему отрезку, включая его концы.','Точка на продолжении прямой тоже коллинеарна, но сумма двух расстояний тогда больше AB.'),
       ('Найди оставшуюся часть','Во второй схеме AB=7 и AP=2. При движении сохраняются обе части. Найди P′B′.','Нужно вычесть уже пройденную часть, а не прибавить её к полной длине.'),
       ('Пройди назад','В третьей схеме A′B′=9 и A′P′=4. Возьми прообраз P′. Найди PB и объясни, почему любая точка нового отрезка имеет прообраз именно на исходном.','Лишь включение образа в A′B′ ещё не показывает, что каждая точка A′B′ достигнута.')],
      [section('Точка между концами',5,2,2),section('Части отрезка длины 7',7,2,2),section('Прообраз произвольной точки',9,4,3)],
      [('Чему равна P′B′ во втором отрезке?','5','7−2=5.'),('Чему равна PB в третьем отрезке?','5','Она равна P′B′=9−4.')],
      'Признак принадлежности отрезку по сумме двух расстояний работает в обе стороны.',
      'Сначала проверь образ каждой исходной точки. Затем возьми произвольную точку между новыми концами.',
      'На чертежах выбран перенос как пример движения. В доказательстве использованы свойства любого движения.',[123])


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[mapping(),mirror_map(),central_map(),isometry(),mirror_length(),central_length(),whole_segment()]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
